CREATE DATABASE IF NOT EXISTS employee_decision_support;
USE employee_decision_support;
CREATE TABLE employees (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, skills VARCHAR(255) NOT NULL, availability_status ENUM('Available','Partially Available','Unavailable') NOT NULL, workload INT NOT NULL);
CREATE TABLE tasks (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(100) NOT NULL, required_skill VARCHAR(100) NOT NULL, estimated_hours INT NOT NULL, status ENUM('Pending','Assigned','In Progress','Completed') DEFAULT 'Pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, assigned_at DATETIME NULL, started_at DATETIME NULL, completed_at DATETIME NULL);
CREATE TABLE employee_availability (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, available_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE schedules (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, task_id INT NOT NULL, schedule_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, FOREIGN KEY (employee_id) REFERENCES employees(id), FOREIGN KEY (task_id) REFERENCES tasks(id));
